diff --git a/test.js b/test.js
index e303a46..b95da83 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,33 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue with default options leaves the active promise untouched', async t => {
+	const limit = pLimit(1);
+
+	const activePromise = limit(() => delay(100, {value: 'active-result'}));
+
+	let queuedRan = false;
+	const queuedPromises = Array.from({length: 3}, () => limit(() => {
+		queuedRan = true;
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	limit.clearQueue();
+
+	// The active promise is untouched: it keeps running and resolves normally.
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+
+	t.is(await activePromise, 'active-result');
+
+	// Every queued function was cleared, none of them ever ran.
+	t.is(queuedRan, false);
+	t.is(queuedPromises.length, 3);
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;

diff --git a/test.js b/test.js
index e303a46..f81a41b 100644
--- a/test.js
+++ b/test.js
@@ -193,6 +193,38 @@ test('clearQueue', async t => {
 	t.is(limit.pendingCount, 0);
 });

+test('clearQueue with default options leaves the active promise untouched', async t => {
+	const limit = pLimit(1);
+
+	const activePromise = limit(() => delay(100, 'active-result'));
+
+	let queuedRan = false;
+	const queuedPromises = Array.from({length: 3}, () => limit(() => {
+		queuedRan = true;
+	}));
+
+	await Promise.resolve();
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 3);
+
+	// The public API is unchanged: `clearQueue()` still returns nothing.
+	t.is(limit.clearQueue(), undefined);
+
+	// The active promise is untouched: it keeps running and resolves normally.
+	t.is(limit.activeCount, 1);
+	t.is(limit.pendingCount, 0);
+
+	t.is(await activePromise, 'active-result');
+
+	// Every queued function was cleared: none of them ever ran, and without
+	// `rejectOnClear` their promises are left neither resolved nor rejected.
+	t.is(queuedRan, false);
+	t.is(await Promise.race([...queuedPromises, delay(50, 'never-settled')]), 'never-settled');
+
+	t.is(limit.activeCount, 0);
+	t.is(limit.pendingCount, 0);
+});
+
 // Node.js 20 has a bug where DOMException is not properly handled by AVA's `throwsAsync`.
 const testClearQueueRejects = process.versions.node.startsWith('20.') ? test.skip : test;
